function fuelRequired(distanceNm, speedKn, consumptionLitresPerHour, marginPercent) {
    const hours = distanceNm / speedKn;
    const fuel = hours * consumptionLitresPerHour * (1 + marginPercent / 100);
    return fuel;
}
```

