function nmeaChecksum(sentence) {
    let xorSum = 0;
    for (let i = 0; i < sentence.length; i++) {
        xorSum ^= sentence.charCodeAt(i);
    }
    return xorSum.toString(16).toUpperCase().padStart(2, '0');
}
```

