```js
function hoursToHHMM(hours) {
    const totalMinutes = Math.round(hours * 60);
    const hoursInt = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    return `${String(hoursInt).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
}
```

```js
function averageSpeed(legs) {
    let totalDistance = 0;
    let totalHours = 0;

    for (const leg of legs) {
        totalDistance += leg.distanceNm;
        totalHours += leg.hours;
    }

    if (totalHours === 0) {
        return null;
    }

    return totalDistance / totalHours;
}
```
